// BLOCK 2 — "Map carefully / duplicate the app"
// Phase 1: recolored Europe map with dropped pins, one wrong (RED) location.
// Phase 2: an Apify actor config card that duplicates, swaps its Task, then
// cascades into a fanned stack — one per task. Two phases handed off with an
// opacity crossfade (never through black). Root is transparent.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { springIn, staggeredSpring, ambientDrift } from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};
const RED = "#FF3B30";
const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_MONO = "monospace";

// Europe framing — europe.svg viewBox in world-map units; pins map into this box.
const VB = { x: 895, y: 55, w: 305, h: 245 };
// The bleeding location — pinned near the centre, larger than the rest.
const BAD = { x: ((1048 - 895) / 305) * 100, y: ((182 - 55) / 245) * 100 };

// Pin icon (Phosphor MapPin) — anchored at its bottom tip.
const PIN_PATH =
  "M128,64a40,40,0,1,0,40,40A40,40,0,0,0,128,64Zm0,64a24,24,0,1,1,24-24A24,24,0,0,1,128,128Zm0-112a88.1,88.1,0,0,0-88,88c0,31.4,14.51,64.68,42,96.25a254.19,254.19,0,0,0,41.45,38.3,8,8,0,0,0,9.18,0A254.19,254.19,0,0,0,174,200.25c27.45-31.57,42-64.85,42-96.25A88.1,88.1,0,0,0,128,16Zm0,206c-16.53-13-72-60.75-72-118a72,72,0,0,1,144,0C200,161.23,144.53,209,128,222Z";

// European location anchors in world-map units (cluster pins on real land).
const ANCHORS: [number, number][] = [
  [957, 160], [985, 165], [1005, 188], [985, 230], [948, 262], [1016, 175],
  [1060, 160], [1055, 185], [1035, 197], [1075, 190], [1045, 205], [1062, 228],
  [1062, 172], [1090, 158], [1096, 192], [1119, 193], [1132, 221], [1083, 214],
  [1100, 248], [1157, 174], [1088, 110], [1060, 112], [1110, 95], [1048, 145],
];

// ---------------------------------------------------------------------------
// Phase 2 helper — the clone's Task value swaps through 2–3 short labels.
// ---------------------------------------------------------------------------
const SwapTaskValue: React.FC<{ frame: number; fontSize: number }> = ({
  frame,
  fontSize,
}) => {
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const op0 = interpolate(frame, [341, 350], [1, 0], clamp);
  const op1 = Math.min(
    interpolate(frame, [341, 350], [0, 1], clamp),
    interpolate(frame, [352, 361], [1, 0], clamp)
  );
  const op2 = interpolate(frame, [352, 361], [0, 1], clamp);
  const stages: [string, number][] = [
    ["Berlin", op0],
    ["Prague", op1],
    ["Munich", op2],
  ];
  const base: React.CSSProperties = {
    fontFamily: FONT_MARKETING,
    fontSize,
    fontWeight: 600,
    color: COLORS.text,
    lineHeight: 1,
    whiteSpace: "nowrap",
  };
  return (
    <span style={{ position: "relative", display: "inline-block" }}>
      <span style={{ ...base, opacity: 0 }}>Munich</span>
      {stages.map(([label, op], i) => (
        <span key={i} style={{ ...base, position: "absolute", left: 0, top: 0, opacity: op }}>
          {label}
        </span>
      ))}
    </span>
  );
};

// ---------------------------------------------------------------------------
// Phase 2 helper — a single Apify actor config card.
// ---------------------------------------------------------------------------
const ActorCard: React.FC<{
  frame: number;
  fps: number;
  base: number;
  W: number;
  H: number;
  left: number;
  top: number;
  z: number;
  delay: number;
  preset: "SNAPPY" | "ELASTIC" | "LIQUID";
  dimOpacity: number;
  cardScale: number;
  scrim: number;
  driftX: number;
  driftY: number;
  taskNode: React.ReactNode;
}> = ({
  frame, fps, base, W, H, left, top, z, delay, preset,
  dimOpacity, cardScale, scrim, driftX, driftY, taskNode,
}) => {
  const p = springIn(frame, fps, delay, preset);
  const entrScale = interpolate(p, [0, 1], [0.9, 1]);
  const entrY = interpolate(p, [0, 1], [base * 0.025, 0]);
  const pad = base * 0.022;
  const fieldH = base * 0.02;

  return (
    <div
      style={{
        position: "absolute",
        left,
        top,
        width: W,
        height: H,
        zIndex: z,
        boxSizing: "border-box",
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: base * 0.016,
        padding: pad,
        display: "flex",
        flexDirection: "column",
        opacity: p * dimOpacity,
        transform: `translate(${driftX}px, ${entrY + driftY}px) scale(${entrScale * cardScale})`,
        transformOrigin: "50% 40%",
        boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
      }}
    >
      {/* Title row: Apify chip + name + window buttons */}
      <div style={{ display: "flex", alignItems: "center", gap: base * 0.012, marginBottom: base * 0.02 }}>
        <Img
          src={staticFile("assets/apify/Apify symbol colors.svg")}
          style={{ width: base * 0.03, height: base * 0.03, objectFit: "contain" }}
        />
        <span style={{ fontFamily: FONT_MARKETING, fontSize: base * 0.022, fontWeight: 600, color: COLORS.text }}>
          Store Scraper
        </span>
        <div style={{ flex: 1 }} />
        <div style={{ display: "flex", gap: base * 0.008 }}>
          {[0, 1, 2].map((i) => (
            <div key={i} style={{ width: base * 0.03, height: base * 0.016, background: "rgba(255,255,255,0.07)", borderRadius: base * 0.004 }} />
          ))}
        </div>
      </div>

      {/* Two dim config field rows (chrome) */}
      <div style={{ display: "flex", flexDirection: "column", gap: base * 0.012 }}>
        {[0, 1].map((i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: base * 0.012 }}>
            <div style={{ width: "26%", height: fieldH, background: "rgba(255,255,255,0.10)", borderRadius: base * 0.004 }} />
            <div style={{ flex: 1, height: fieldH, background: "rgba(255,255,255,0.045)", border: `1px solid ${COLORS.border}`, borderRadius: base * 0.004 }} />
          </div>
        ))}
      </div>

      {/* Task field — highlighted orange, pushed to bottom band (stays visible on stacked cards) */}
      <div
        style={{
          marginTop: "auto",
          display: "flex",
          alignItems: "center",
          gap: base * 0.014,
          background: COLORS.orangeTint,
          border: `1px solid ${COLORS.orange}`,
          borderRadius: base * 0.008,
          padding: `${base * 0.016}px ${base * 0.018}px`,
        }}
      >
        <div style={{ width: base * 0.005, height: base * 0.05, background: COLORS.orange, borderRadius: base * 0.003 }} />
        <div style={{ display: "flex", flexDirection: "column", gap: base * 0.006 }}>
          <span style={{ fontFamily: FONT_MONO, fontSize: base * 0.014, letterSpacing: 2, color: COLORS.orange }}>TASK</span>
          {taskNode}
        </div>
      </div>

      {/* Depth scrim on cards further back in the stack */}
      {scrim > 0 && (
        <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.016, background: "#000", opacity: scrim, pointerEvents: "none" }} />
      )}
    </div>
  );
};

// ---------------------------------------------------------------------------
// Scene
// ---------------------------------------------------------------------------
const Block2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  // ===== Phase handoff (crossfade, never through black) =====
  const phase1Op = interpolate(frame, [304, 316], [1, 0], clamp);

  // ================= PHASE 1 — MAP =================
  const NUM_PINS = 46;
  const badIdx = 6;
  const pins = React.useMemo(() => {
    const arr: { x: number; y: number }[] = [];
    let s = 7;
    const rnd = () => {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };
    for (let i = 0; i < NUM_PINS; i++) {
      const a = ANCHORS[i % ANCHORS.length];
      const wx = a[0] + (rnd() - 0.5) * 16;
      const wy = a[1] + (rnd() - 0.5) * 13;
      arr.push({ x: ((wx - VB.x) / VB.w) * 100, y: ((wy - VB.y) / VB.h) * 100 });
    }
    return arr;
  }, []);

  // f0 — map recolors / springs in (LIQUID)
  const mapIn = springIn(frame, vfps, 0, "LIQUID");
  const mapSc = interpolate(mapIn, [0, 1], [0.94, 1]);
  const mapTy = interpolate(mapIn, [0, 1], [30, 0]);
  const mDriftX = ambientDrift(frame, 2, 110, "map-x");
  const mDriftY = ambientDrift(frame, 2, 130, "map-y");

  // f99 — the one wrong pin turns RED, grows, and a pulsing ring begins.
  const badGrow = springIn(frame, vfps, 99, "SNAPPY");
  const ringT = ((frame - 99) % 30) / 30; // loops continuously through the hold
  const ringScale = 1 + ringT;
  const ringOp = frame >= 99 ? Math.max(0, 1 - ringT) * 0.5 * badGrow : 0;

  // f74 — gentle emphasis: a subtle orange focus ring around the bad area,
  // fading out as the red takes over.
  const focusIn = springIn(frame, vfps, 74, "GENTLE");
  const focusScale = interpolate(focusIn, [0, 1], [1.25, 1]);
  const focusOp = focusIn * 0.38 * interpolate(frame, [99, 113], [1, 0], clamp);

  // f119 — tiny callout: rating ticking DOWN.
  const calloutIn = springIn(frame, vfps, 119, "SNAPPY");
  const rating = interpolate(frame, [119, 152], [4.6, 4.1], clamp);

  const mapUrl = staticFile("assets/other/europe.svg");

  // ================= PHASE 2 — ACTOR CARD STACK =================
  const W = width * 0.30;
  const H = base * 0.29;
  const gapX = base * 0.07;
  const gapY = base * 0.115;
  const cDriftX = ambientDrift(frame, 2, 120, "card-x");
  const cDriftY = ambientDrift(frame, 2, 140, "card-y");
  const taskFont = base * 0.028;

  const taskNodes: React.ReactNode[] = [
    <span style={{ fontFamily: FONT_MARKETING, fontSize: taskFont, fontWeight: 600, color: COLORS.text, lineHeight: 1 }}>Berlin</span>,
    <SwapTaskValue frame={frame} fontSize={taskFont} />,
    <span style={{ fontFamily: FONT_MARKETING, fontSize: taskFont, fontWeight: 600, color: COLORS.text, lineHeight: 1 }}>Hamburg</span>,
    <span style={{ fontFamily: FONT_MARKETING, fontSize: taskFont, fontWeight: 600, color: COLORS.text, lineHeight: 1 }}>Cologne</span>,
  ];

  // slot 0 = primary (f313), slot 1 = clone popping behind-right (f320),
  // slots 2,3 = cascade in (f374, f386). Front card (slot 0) centred.
  const cardDefs: { delay: number; preset: "SNAPPY" | "ELASTIC" }[] = [
    { delay: 313, preset: "SNAPPY" },
    { delay: 320, preset: "ELASTIC" },
    { delay: 374, preset: "ELASTIC" },
    { delay: 386, preset: "ELASTIC" },
  ];

  return (
    <AbsoluteFill>
      {/* ---------------- PHASE 1: MAP ---------------- */}
      <AbsoluteFill
        style={{
          padding: base * 0.06,
          opacity: mapIn * phase1Op,
          transform: `translate(${mDriftX}px, ${mapTy + mDriftY}px) scale(${mapSc})`,
        }}
      >
        <div style={{ position: "absolute", inset: `${base * 0.08}px ${base * 0.1}px` }}>
          <div style={{ position: "absolute", top: 0, bottom: 0, left: "19.25%", width: "61.5%" }}>
            {/* Recolored Europe: SVG as a CSS mask filled with COLORS.card */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: COLORS.card,
                WebkitMaskImage: `url(${mapUrl})`,
                maskImage: `url(${mapUrl})`,
                WebkitMaskRepeat: "no-repeat",
                maskRepeat: "no-repeat",
                WebkitMaskPosition: "center",
                maskPosition: "center",
                WebkitMaskSize: "100% 100%",
                maskSize: "100% 100%",
              }}
            />
            {/* Country borders drawn back on top */}
            <div style={{ position: "absolute", inset: 0, opacity: 0.85 }}>
              <Img
                src={staticFile("assets/other/europe-borders.svg")}
                style={{ width: "100%", height: "100%", objectFit: "fill" }}
              />
            </div>

            {/* f74 — subtle focus ring around the bad area */}
            {focusOp > 0.001 && (
              <div
                style={{
                  position: "absolute",
                  left: `${BAD.x}%`,
                  top: `${BAD.y}%`,
                  width: base * 0.11,
                  height: base * 0.11,
                  borderRadius: "50%",
                  border: `${base * 0.0035}px solid ${COLORS.orange}`,
                  transform: `translate(-50%, -66%) scale(${focusScale})`,
                  opacity: focusOp,
                  zIndex: 8,
                }}
              />
            )}

            {/* Pins — dropped staggered from f0; one turns RED at f99 */}
            {pins.map((pin, i) => {
              const isBad = i === badIdx;
              const pinIn = staggeredSpring(frame, vfps, i, 0, 0.6, "ELASTIC");
              const size = isBad
                ? base * 0.045 + interpolate(badGrow, [0, 1], [0, base * 0.03])
                : base * 0.03;
              const x = isBad ? BAD.x : pin.x;
              const y = isBad ? BAD.y : pin.y;

              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: `${x}%`,
                    top: `${y}%`,
                    width: size,
                    height: size,
                    transform: `translate(-50%, -88%) scale(${pinIn})`,
                    transformOrigin: "50% 88%",
                    zIndex: isBad ? 10 : 1,
                  }}
                >
                  {/* Red pulsing alert ring on the wrong location */}
                  {isBad && (
                    <div
                      style={{
                        position: "absolute",
                        left: "50%",
                        top: "41%",
                        width: size * 1.5,
                        height: size * 1.5,
                        borderRadius: "50%",
                        background: RED,
                        transform: `translate(-50%, -50%) scale(${ringScale})`,
                        opacity: ringOp,
                      }}
                    />
                  )}
                  {/* Orange pin (fades under the red for the bad one) */}
                  <svg
                    viewBox="0 0 256 256"
                    width={size}
                    height={size}
                    style={{
                      position: "absolute",
                      inset: 0,
                      display: "block",
                      opacity: isBad ? 1 - badGrow : 1,
                      filter: `drop-shadow(0 ${base * 0.002}px ${base * 0.004}px rgba(0,0,0,0.5))`,
                    }}
                  >
                    <path d={PIN_PATH} fill={COLORS.orange} />
                  </svg>
                  {/* Red pin on top for the bad one */}
                  {isBad && (
                    <svg
                      viewBox="0 0 256 256"
                      width={size}
                      height={size}
                      style={{
                        position: "absolute",
                        inset: 0,
                        display: "block",
                        opacity: badGrow,
                        filter: `drop-shadow(0 ${base * 0.004}px ${base * 0.006}px rgba(0,0,0,0.6))`,
                      }}
                    >
                      <path d={PIN_PATH} fill={RED} />
                    </svg>
                  )}
                </div>
              );
            })}

            {/* f119 — tiny rating callout ticking DOWN, near the bad pin */}
            {calloutIn > 0.001 && (
              <div
                style={{
                  position: "absolute",
                  left: `${BAD.x}%`,
                  top: `${BAD.y}%`,
                  transform: `translate(18%, -230%) scale(${interpolate(calloutIn, [0, 1], [0.85, 1])})`,
                  transformOrigin: "0% 100%",
                  opacity: calloutIn,
                  display: "flex",
                  alignItems: "center",
                  gap: base * 0.008,
                  background: COLORS.card,
                  border: `1px solid ${COLORS.border}`,
                  borderRadius: base * 0.008,
                  padding: `${base * 0.008}px ${base * 0.012}px`,
                  boxShadow: "0 10px 28px rgba(0,0,0,0.5)",
                  zIndex: 12,
                }}
              >
                <span style={{ fontFamily: FONT_MARKETING, fontSize: base * 0.02, color: COLORS.orange }}>★</span>
                <span style={{ fontFamily: FONT_MONO, fontSize: base * 0.024, fontWeight: 700, color: COLORS.text }}>
                  {rating.toFixed(1)}
                </span>
                <span style={{ fontFamily: FONT_MARKETING, fontSize: base * 0.02, color: COLORS.orange }}>▾</span>
              </div>
            )}
          </div>
        </div>
      </AbsoluteFill>

      {/* ---------------- PHASE 2: DUPLICATE THE APP ---------------- */}
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "relative", width: 0, height: 0 }}>
          {cardDefs.map((def, slot) => (
            <ActorCard
              key={slot}
              frame={frame}
              fps={vfps}
              base={base}
              W={W}
              H={H}
              left={-W / 2 + slot * gapX}
              top={-H / 2 + slot * gapY}
              z={50 - slot * 10}
              delay={def.delay}
              preset={def.preset}
              dimOpacity={1 - slot * 0.07}
              cardScale={1 - slot * 0.02}
              scrim={slot * 0.1}
              driftX={cDriftX}
              driftY={cDriftY}
              taskNode={taskNodes[slot]}
            />
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export const fps = 25;
export const durationInFrames = 460;
export default Block2;
